using KafkaPartitionLab;using Xunit;public sealed class KafkaTests
{[Fact]public void Same_key_preserves_partition_and_order(){var t=new TopicLog(4);var a=t.Produce("k","a");var b=t.Produce("k","b");Assert.Equal(a.Partition,b.Partition);Assert.Equal(a.Offset+1,b.Offset);}[Fact]public void Different_groups_have_independent_offsets(){var t=new TopicLog(1);var r=t.Produce("k","v");var a=new ConsumerGroup(t);var b=new ConsumerGroup(t);a.Commit(r);Assert.Empty(a.Poll(0));Assert.Single(b.Poll(0));}[Fact]public void Uncommitted_record_is_redelivered(){var t=new TopicLog(1);t.Produce("k","v");var g=new ConsumerGroup(t);Assert.Equal(g.Poll(0),g.Poll(0));}[Fact]public void Commit_advances_to_next_offset(){var t=new TopicLog(1);var a=t.Produce("k","a");t.Produce("k","b");var g=new ConsumerGroup(t);g.Commit(a);Assert.Equal("b",Assert.Single(g.Poll(0)).Value);}}
